// Insert inserts the record into the database
func (t *MaintenanceRegistration) Insert(runTrigger bool) bool {
	// OnInsert trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnInsert(); err != nil {
			fmt.Printf("Error: OnInsert trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, MaintenanceRegistrationTableName)

	// Collect arguments for INSERT
	args := []interface{}{
		t.Fa_no,
		t.Line_no,
		t.Service_date,
		t.Maintenance_vendor_no,
		t.Comment,
		t.Service_agent_name,
		t.Service_agent_phone_no,
		t.Service_agent_mobile_phone,
	}

	// Build SQL with placeholders. A taken key inserts nothing (ON CONFLICT … DO NOTHING) instead
	// of failing: on PostgreSQL a failed INSERT would abort the transaction
	sqlStr := fmt.Sprintf(`INSERT INTO "%s" (fa_no, line_no, service_date, maintenance_vendor_no, comment, service_agent_name, service_agent_phone_no, service_agent_mobile_phone) VALUES (?, ?, ?, ?, ?, ?, ?, ?) ON CONFLICT (fa_no, line_no) DO NOTHING`, tableName)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(args))

	result, err := t.exec().Exec(sqlStr, args...)
	if err != nil {
		fmt.Printf("Error: Failed to insert Maintenance_Registration: %v\n", err)
		return false
	}
	// The key is taken (INSERT fails in the classic way: "<Table> <key> already exists")
	if n, err := result.RowsAffected(); err == nil && n == 0 {
		_, key := t.recordKey()
		t.triggerErr = apperrors.TableRecordExists(MaintenanceRegistrationTableName, key)
		return false
	}
	// The record as written: its xRec from now on (a following Modify or Rename compares with it)
	t.StoreOldValues()
	return true
}

// InsertAll inserts records in bulk (demo data, imports): multi-row INSERT statements, one
// round trip per batch instead of one per record. With runTrigger every record's OnInsert
// trigger runs first, as Insert(true) would; the first failure stops before anything is
// written. Records are written with the receiver's database and company. Errors are
// *tables.BatchInsertError (Index = the record in records). Use it in a transaction: a
// failed batch leaves the earlier batches written.
func (t *MaintenanceRegistration) InsertAll(records []*MaintenanceRegistration, runTrigger bool) error {
	rows := make([][]interface{}, 0, len(records))
	for i, r := range records {
		r.triggerErr = nil
		if runTrigger {
			if err := r.runOnInsert(); err != nil {
				r.triggerErr = err
				return &tables.BatchInsertError{Index: i, Trigger: true, Err: err}
			}
		}
		rows = append(rows, []interface{}{
			r.Fa_no,
			r.Line_no,
			r.Service_date,
			r.Maintenance_vendor_no,
			r.Comment,
			r.Service_agent_name,
			r.Service_agent_phone_no,
			r.Service_agent_mobile_phone,
		})
	}
	tableName := fmt.Sprintf("%s$%s", t.company, MaintenanceRegistrationTableName)
	columns := []string{"fa_no", "line_no", "service_date", "maintenance_vendor_no", "comment", "service_agent_name", "service_agent_phone_no", "service_agent_mobile_phone"}
	return tables.InsertRows(t.exec(), t.dbType, tableName, columns, rows)
}

// Modify updates the record in the database
func (t *MaintenanceRegistration) Modify(runTrigger bool) bool {
	// OnModify trigger of the business logic, then the field checks of the definition
	t.triggerErr = nil
	if runTrigger {
		if err := t.runOnModify(); err != nil {
			fmt.Printf("Error: OnModify trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	// A changed primary key is a rename: run the OnRename trigger
	// before it is written; xRec values are available through OldValue
	keyChanged := false
	if t.oldValues != nil {
		if t.hasFieldChanged("fa_no") {
			keyChanged = true
		}
		if t.hasFieldChanged("line_no") {
			keyChanged = true
		}
	}
	if runTrigger && keyChanged {
		if err := t.runOnRename(); err != nil {
			fmt.Printf("Error: OnRename trigger failed: %v\n", err)
			t.triggerErr = err
			return false
		}
	}
	tableName := fmt.Sprintf("%s$%s", t.company, MaintenanceRegistrationTableName)

	// Build dynamic SQL based on field tracking
	var setClauses []string
	var values []interface{}

	// If we have old values (loaded from Get), only update changed fields.
	// Changed primary key fields are renamed in place (Rename): they are SET to the
	// new value while the WHERE clause matches the old one.
	if t.oldValues != nil {
		if t.hasFieldChanged("fa_no") {
			setClauses = append(setClauses, "fa_no = ?")
			values = append(values, t.Fa_no)
		}
		if t.hasFieldChanged("line_no") {
			setClauses = append(setClauses, "line_no = ?")
			values = append(values, t.Line_no)
		}
		if t.hasFieldChanged("service_date") {
			setClauses = append(setClauses, "service_date = ?")
			values = append(values, t.Service_date)
		}
		if t.hasFieldChanged("maintenance_vendor_no") {
			setClauses = append(setClauses, "maintenance_vendor_no = ?")
			values = append(values, t.Maintenance_vendor_no)
		}
		if t.hasFieldChanged("comment") {
			setClauses = append(setClauses, "comment = ?")
			values = append(values, t.Comment)
		}
		if t.hasFieldChanged("service_agent_name") {
			setClauses = append(setClauses, "service_agent_name = ?")
			values = append(values, t.Service_agent_name)
		}
		if t.hasFieldChanged("service_agent_phone_no") {
			setClauses = append(setClauses, "service_agent_phone_no = ?")
			values = append(values, t.Service_agent_phone_no)
		}
		if t.hasFieldChanged("service_agent_mobile_phone") {
			setClauses = append(setClauses, "service_agent_mobile_phone = ?")
			values = append(values, t.Service_agent_mobile_phone)
		}

		// If nothing changed, skip update
		if len(setClauses) == 0 {
			return true // No changes, success
		}
	} else {
		// No old values (fresh record), update all fields
		setClauses = append(setClauses, "service_date = ?")
		values = append(values, t.Service_date)
		setClauses = append(setClauses, "maintenance_vendor_no = ?")
		values = append(values, t.Maintenance_vendor_no)
		setClauses = append(setClauses, "comment = ?")
		values = append(values, t.Comment)
		setClauses = append(setClauses, "service_agent_name = ?")
		values = append(values, t.Service_agent_name)
		setClauses = append(setClauses, "service_agent_phone_no = ?")
		values = append(values, t.Service_agent_phone_no)
		setClauses = append(setClauses, "service_agent_mobile_phone = ?")
		values = append(values, t.Service_agent_mobile_phone)
	}

	// Add WHERE clause value (primary key as loaded, so a renamed key still matches)
	if old, ok := t.oldValues["fa_no"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Fa_no)
	}
	if old, ok := t.oldValues["line_no"]; ok {
		values = append(values, old)
	} else {
		values = append(values, t.Line_no)
	}

	// Build and execute SQL
	sqlStr := fmt.Sprintf(`UPDATE "%s" SET %s WHERE 1=1 AND fa_no = ? AND line_no = ?`,
		tableName,
		strings.Join(setClauses, ", "),
	)

	// Convert placeholders for PostgreSQL
	sqlStr = t.convertPlaceholders(sqlStr, len(values))

	_, err := t.exec().Exec(sqlStr, values...)
	if err != nil {
		fmt.Printf("Error: Failed to modify Maintenance_Registration: %v\n", err)
		return false
	}
	// The stored record now matches the current values (including a renamed key)
	if t.oldValues != nil {
		t.StoreOldValues()
	}
	return true
}

// hasFieldChanged checks if a field value has changed from oldValues
func (t *MaintenanceRegistration) hasFieldChanged(fieldName string) bool {
	if t.oldValues == nil {
		return true // No old values, assume changed
	}

	oldValue, exists := t.oldValues[fieldName]
	if !exists {
		return true // Field not in old values, assume changed
	}
	_ = oldValue // Suppress unused variable when all fields are PKs

	// Compare old vs new value based on field name (with type assertion)
	switch fieldName {
	case "fa_no":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Fa_no.Equal(old)
		}
	case "line_no":
		if old, ok := oldValue.(int); ok {
			return t.Line_no != old
		}
		return true // Type mismatch, assume changed
	case "service_date":
		if old, ok := oldValue.(types.Date); ok {
			return !t.Service_date.Equal(old)
		}
	case "maintenance_vendor_no":
		if old, ok := oldValue.(types.Code); ok {
			return !t.Maintenance_vendor_no.Equal(old)
		}
	case "comment":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Comment.Equal(old)
		}
	case "service_agent_name":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Service_agent_name.Equal(old)
		}
	case "service_agent_phone_no":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Service_agent_phone_no.Equal(old)
		}
	case "service_agent_mobile_phone":
		if old, ok := oldValue.(types.Text); ok {
			return !t.Service_agent_mobile_phone.Equal(old)
		}
	}

	return false
}

