		for _, l := range t.registeredLogic() {
			if trg, ok := l.(MaintenanceRegistrationOnValidate_Fa_no); ok {
				if err := trg.OnValidate_Fa_no(t); err != nil {
					return err
				}
			}
		}
		return nil
