// CalcSums sets each of the decimal or integer fields to its total over the records matching
// the current filters (CalcSums)
func (t *MaintenanceRegistration) CalcSums(fieldNames ...string) error {
	tableName := fmt.Sprintf("%s$%s", t.company, MaintenanceRegistrationTableName)
	where, args := t.buildWhereClause()
	for _, name := range fieldNames {
		var column string
		switch strings.ToLower(name) {
		case "line_no":
			column = "line_no"
		default:
			return fmt.Errorf("CalcSums: %s is not a decimal or integer field of Maintenance_Registration", name)
		}
		query := t.convertPlaceholders(fmt.Sprintf(`SELECT CAST(COALESCE(SUM(%s), 0) AS TEXT) FROM "%s" WHERE %s`, column, tableName, where), len(args))
		var total string
		if err := t.exec().QueryRow(query, args...).Scan(&total); err != nil {
			return fmt.Errorf("CalcSums Maintenance_Registration.%s: %w", column, err)
		}
		switch column {
		case "line_no":
			f, err := strconv.ParseFloat(total, 64)
			if err != nil {
				return fmt.Errorf("CalcSums Maintenance_Registration.%s: %w", column, err)
			}
			t.Line_no = int(f)
		}
	}
	return nil
}

